export const getBlogPostBySlug = (slug) => {
  if (!slug) return null;
  const cleanSlug = slug.toLowerCase().trim();
  return (
    blogPosts.find(
      (p) => p.slug === cleanSlug || (Array.isArray(p.aliases) && p.aliases.includes(cleanSlug))
    ) || null
  );
};
